code.cpp:
// Build heights row by row, apply histogram solution
vector<int> heights(c,0);
int maxArea=0;
for(int i=0;i<r;i++){
  for(int j=0;j<c;j++) heights[j]=mat[i][j]?heights[j]+1:0;
  // Apply largest rect in histogram on heights
  stack<int> st;
  for(int j=0;j<=c;j++){
    int h=j==c?0:heights[j];
    while(!st.empty()&&heights[st.top()]>h){
      int ht=heights[st.top()];st.pop();
      int w=st.empty()?j:j-st.top()-1;
      maxArea=max(maxArea,ht*w);
    }
    st.push(j);
  }
}
cout<<maxArea;

